//! The binary format is the on-disk contract, so these tests pin the magic, the
//! round trip, UTF-8 handling, and the budget for decoding a whole Bible.
//!
//! Every translation here is synthetic text generated by the test itself; no
//! Bible text appears in the repository.

use bible_core::books;
use bible_core::format;
use bible_core::model::{
    Mark, MarkKind, Span, SpanStyle, Translation, TranslationBuilder, TranslationMeta, Verse,
};

fn sample_meta() -> TranslationMeta {
    TranslationMeta {
        id: "smp".to_owned(),
        abbreviation: "SMP".to_owned(),
        name: "Sample Translation".to_owned(),
        language: "en".to_owned(),
        licence: "Public domain".to_owned(),
        copyright: "Public domain".to_owned(),
        provenance: "generated by the test suite".to_owned(),
        origin: "test".to_owned(),
        book_titles: vec!["Beginnings".to_owned(), "Departure".to_owned()],
        red_letter: true,
        paragraphs: true,
        headings: true,
    }
}

/// A translation that fills Genesis, with every mark and span kind in it, so a
/// round trip exercises the whole model.
fn genesis_sample() -> Translation {
    let mut builder = TranslationBuilder::new(sample_meta());
    for chapter in 1..=books::book(0).expect("Genesis").chapters {
        for verse in 1..=books::verses_in_chapter(0, chapter).expect("chapter") {
            let text = format!("line {verse} of chapter {chapter} runs on");
            builder
                .push_verse(verse as u8, &text, |sink| {
                    match verse {
                        1 => {
                            sink.mark(MarkKind::Paragraph, 0)?;
                            sink.heading(0, &format!("Chapter {chapter}"))?;
                        }
                        2 => {
                            sink.mark_with_level(MarkKind::Poetry, 0, 2)?;
                            sink.span(SpanStyle::WordsOfChrist, 0, 4)?;
                        }
                        3 => {
                            sink.mark(MarkKind::StanzaBreak, 0)?;
                            sink.span(SpanStyle::TranslatorAddition, 5, 7)?;
                        }
                        4 => {
                            sink.superscription("A song of the test suite")?;
                            sink.span(SpanStyle::DivineName, 0, 4)?;
                        }
                        _ => {
                            sink.span(SpanStyle::Selah, 0, 4)?;
                        }
                    }
                    Ok(())
                })
                .expect("verse");
        }
    }
    builder.finish()
}

/// A full-Bible translation of generated text, used for the decode budget.
fn synthetic_full_bible() -> Translation {
    let mut builder = TranslationBuilder::new(sample_meta());
    for book in &books::BOOKS {
        for chapter in 1..=book.chapters {
            let count = books::verses_in_chapter(book.index, chapter).expect("chapter");
            for verse in 1..=count {
                let text = format!(
                    "{verse} of {chapter} in {} keeps the generated words flowing onward",
                    book.name
                );
                builder.push_plain_verse(verse as u8, &text).expect("verse");
            }
        }
    }
    builder.finish()
}

#[test]
fn encoded_bytes_start_with_the_magic() {
    let bytes = format::encode(&genesis_sample()).expect("encode");
    assert_eq!(&bytes[..4], &format::MAGIC);
    assert_eq!(&bytes[..4], b"BIBL");
    assert_eq!(&bytes[4..6], &format::VERSION.to_le_bytes());
}

#[test]
fn round_trip_restores_every_field() {
    let original = genesis_sample();
    let bytes = format::encode(&original).expect("encode");
    let decoded = format::decode(&bytes).expect("decode");

    assert_eq!(decoded, original);
    assert_eq!(decoded.meta(), original.meta());
    assert_eq!(decoded.text(), original.text());
    assert_eq!(decoded.extra(), original.extra());
    assert_eq!(decoded.verses(), original.verses());
    assert_eq!(decoded.marks(), original.marks());
    assert_eq!(decoded.spans(), original.spans());

    let first: &Verse = &decoded.verses()[0];
    assert_eq!(first.number, 1);
    assert_eq!(first.marks_len, 2);
    let marks: &[Mark] = decoded.marks();
    assert_eq!(marks[0].kind, MarkKind::Paragraph);
    assert_eq!(marks[1].kind, MarkKind::Heading);
    assert_eq!(decoded.mark_text(&marks[1]), "Chapter 1");
    let spans: &[Span] = decoded.spans();
    assert_eq!(spans[0].style, SpanStyle::WordsOfChrist);
}

#[test]
fn round_trip_preserves_multibyte_text_exactly() {
    let mut builder = TranslationBuilder::new(sample_meta());
    builder
        .push_verse(1, "café λόγος — 🙂", |sink| {
            sink.span(SpanStyle::DivineName, 0, 5)?;
            Ok(())
        })
        .expect("verse");
    builder.push_plain_verse(2, "Ωmega and ﬁne").expect("verse");
    let original = builder.finish();

    let bytes = format::encode_with_level(&original, 9).expect("encode");
    let decoded = format::decode(&bytes).expect("decode");

    assert_eq!(decoded.text(), original.text());
    assert_eq!(decoded.verse_text(&decoded.verses()[0]), "café λόγος — 🙂");
    assert_eq!(
        decoded.verse_text(&decoded.verses()[0]).len(),
        "café λόγος — 🙂".len()
    );
    assert_eq!(decoded.verse_text(&decoded.verses()[1]), "Ωmega and ﬁne");
    assert_eq!(decoded, original);
}

#[test]
fn reads_the_metadata_without_touching_the_body() {
    let sample = genesis_sample();
    let bytes = format::encode(&sample).expect("encode");
    let meta = format::read_meta(&bytes).expect("read metadata");
    assert_eq!(&meta, sample.meta());
}

#[test]
fn materialising_a_chapter_allocates_nothing_per_verse() {
    let decoded =
        format::decode(&format::encode(&synthetic_full_bible()).expect("encode")).expect("decode");
    let chapter = decoded.chapter(18, 119).expect("Psalm 119 has 176 verses");
    assert_eq!(chapter.verses().len(), 176);

    let mut out = String::with_capacity(1 << 20);
    let reserved = out.capacity();
    for _ in 0..3 {
        out.clear();
        chapter.write_text(&mut out);
        assert_eq!(out.capacity(), reserved, "chapter layout reallocated");
    }

    let expected: String = chapter
        .verses()
        .iter()
        .map(|verse| chapter.text(verse))
        .collect();
    assert_eq!(out, expected);
}

#[test]
fn refuses_a_damaged_file() {
    let bytes = format::encode(&genesis_sample()).expect("encode");

    let mut wrong_magic = bytes.clone();
    wrong_magic[0] = b'X';
    assert!(format::decode(&wrong_magic).is_err());

    let mut wrong_version = bytes.clone();
    wrong_version[4] = 9;
    assert!(format::decode(&wrong_version).is_err());

    assert!(format::decode(&bytes[..bytes.len() - 1]).is_err());
    assert!(format::decode(&[]).is_err());
}

#[test]
fn decode_benchmark() {
    let translation = synthetic_full_bible();
    assert_eq!(translation.verses().len(), books::VERSE_COUNT);
    let bytes = format::encode(&translation).expect("encode");

    let start = std::time::Instant::now();
    let decoded = format::decode(&bytes).expect("decode");
    let elapsed = start.elapsed();

    assert_eq!(decoded.verses().len(), books::VERSE_COUNT);
    assert_eq!(decoded.text(), translation.text());
    println!(
        "decode_benchmark: {} verses from {} bytes in {:.2} ms",
        decoded.verses().len(),
        bytes.len(),
        elapsed.as_secs_f64() * 1000.0
    );

    if !cfg!(debug_assertions) {
        assert!(
            elapsed.as_millis() < 50,
            "decoding a full Bible took {elapsed:?}, the budget is 50 ms"
        );
    }
}
